// Everything Kaz is allowed to think with arrives here from the AEP server.
// This node trusts nothing about its size: AEP caps its own context, and this
// caps it again, because the Gateway is what stands in front of the model.
const body = $json.body ?? {};
const text = (value, max) => (typeof value === 'string' ? value.slice(0, max) : '');
const inspect = body.inspect ?? {};

const question = text(body.question, 2000).trim();
if (!question) {
  throw new Error('kaz: empty question');
}

return {
  json: {
    persona: text(body.persona, 4000),
    rules: text(body.rules, 4000),
    levelInstruction: text(body.levelInstruction, 1000),
    helpLevel: Number(body.helpLevel) || 1,
    question,
    history: Array.isArray(body.history)
      ? body.history.slice(-16).map((m) => ({
          role: m && m.role === 'kaz' ? 'kaz' : 'learner',
          content: text(m && m.content, 1200),
        }))
      : [],
    lesson: body.lesson ?? {},
    progress: body.progress ?? {},
    canonical: body.canonical ?? null,
    wantWorkflow: inspect.workflow === true,
    wantExecution: inspect.execution === true,
    webhookPath: text(inspect.webhookPath, 200),
  },
};

// Resolve the learner's saved webhook PATH to exactly one workflow.
//
// AEP never sends a workflow id, and never sends the URL itself - only the
// path, and only after checking the saved URL's host is this n8n. Matching
// happens here because only n8n can see what paths exist.
//
// Fail closed on anything but a single match. This instance holds copies of
// lab workflows (AEP-E2E-...), so an ambiguous path must mean "I can't inspect
// that", never a guess at which copy the learner meant.
const req = $('Read Request').item.json;
const payload = $input.first().json;
const workflows = Array.isArray(payload.data) ? payload.data : [];

const matches = workflows.filter(
  (wf) =>
    Array.isArray(wf.nodes) &&
    wf.nodes.some(
      (node) =>
        node.type === 'n8n-nodes-base.webhook' &&
        String((node.parameters || {}).path || '') === req.webhookPath,
    ),
);

if (matches.length !== 1) {
  return { json: { resolved: false, reason: matches.length === 0 ? 'no_match' : 'ambiguous' } };
}

const wf = matches[0];
return {
  json: {
    resolved: true,
    workflowId: wf.id,
    workflowName: wf.name,
    active: wf.active === true,
    nodes: wf.nodes,
  },
};

// Everything that reaches Gemini passes through here first.
//
// Credentials are dropped whole rather than redacted field by field, every key
// that looks like a secret is replaced, and sizes are capped. What survives is
// the configuration and data needed to explain a failure - node names, types,
// parameters, the last outputs - and nothing else.
const req = $('Read Request').item.json;

const SECRET_KEY = /(key|token|secret|password|passwd|credential|authorization|auth|cookie|bearer|session)/i;

function clean(value, depth) {
  const level = depth || 0;
  if (level > 5) return '[nested]';
  if (typeof value === 'string') return value.length > 800 ? value.slice(0, 800) + '…' : value;
  if (Array.isArray(value)) return value.slice(0, 20).map((entry) => clean(entry, level + 1));
  if (value && typeof value === 'object') {
    // n8n stores headers and query parameters as { name, value } pairs, so the
    // key holding a bearer token is called 'value'. Redacting by key name alone
    // would let { name: 'Authorization', value: 'Bearer ...' } straight through.
    if (typeof value.name === 'string' && SECRET_KEY.test(value.name) && 'value' in value) {
      return Object.assign({}, value, { value: '[redacted]' });
    }
    const out = {};
    for (const [key, entry] of Object.entries(value)) {
      if (SECRET_KEY.test(key)) {
        out[key] = '[redacted]';
        continue;
      }
      out[key] = clean(entry, level + 1);
    }
    return out;
  }
  return value;
}

let workflow = null;
let workflowNote = null;
try {
  const found = $('Find Learner Workflow').item.json;
  if (found && found.resolved) {
    workflow = {
      name: String(found.workflowName || '').slice(0, 120),
      active: found.active === true,
      nodes: (found.nodes || []).slice(0, 60).map((node) => ({
        name: String(node.name || '').slice(0, 120),
        type: String(node.type || '').slice(0, 120),
        disabled: node.disabled === true,
        // 'credentials' is never copied across at all.
        parameters: clean(node.parameters),
      })),
    };
  } else if (found) {
    workflowNote = found.reason === 'ambiguous'
      ? 'Several workflows answer on that webhook path, so I cannot tell which one is yours.'
      : 'No workflow on this n8n answers on that saved webhook path.';
  }
} catch (error) {
  workflow = null;
}

let execution = null;
try {
  const payload = $('Latest Execution').item.json;
  const run = Array.isArray(payload.data) ? payload.data[0] : null;
  if (run) {
    const resultData = ((run.data || {}).resultData) || {};
    const runData = resultData.runData || {};
    const names = Object.keys(runData);
    const tail = names.slice(-3).map((name) => {
      const first = (runData[name] || [])[0] || {};
      const items = (((first.data || {}).main || [])[0] || []).slice(0, 3);
      return {
        node: name,
        error: first.error ? String(first.error.message || '').slice(0, 300) : null,
        output: clean(items.map((item) => (item && item.json) || null)),
      };
    });
    execution = {
      status: run.status,
      startedAt: run.startedAt,
      lastNode: resultData.lastNodeExecuted || null,
      error: resultData.error
        ? {
            message: String(resultData.error.message || '').slice(0, 500),
            node: resultData.error.node ? String(resultData.error.node.name || '') : null,
          }
        : null,
      recentNodes: tail,
    };
  }
} catch (error) {
  execution = null;
}

return { json: { ...req, workflow, workflowNote, execution } };

// Assembles one prompt. The teaching policy is already decided: AEP chose the
// help level and sent only the canonical material that level allows, so this
// node cannot widen it even by accident.
const d = $json;
const lesson = d.lesson || {};
const progress = d.progress || {};

const lines = [];
lines.push(d.persona, '', d.rules, '', d.levelInstruction, '');
lines.push('=== WHERE THE LEARNER IS ===');
lines.push('Lab: ' + (lesson.labTitle || 'unknown'));
lines.push('Step: ' + (lesson.chunkTitle || 'unknown') + ' (' + (lesson.chunkKind || '') + ')');
if (Array.isArray(lesson.outline) && lesson.outline.length) {
  lines.push('Lesson steps: ' + lesson.outline.join(' > '));
}
lines.push('Labs completed: ' + (progress.completedLabs ?? 0) + '/' + (progress.totalLabs ?? 10));
lines.push('This lab complete: ' + (progress.labComplete ? 'yes' : 'not yet'));
const evidence = progress.evidence || {};
const proved = Object.keys(evidence);
if (proved.length) {
  lines.push('Proved so far here: ' + proved.map((k) => k + '=' + evidence[k]).join(', '));
}
if (Array.isArray(progress.hintsRevealed) && progress.hintsRevealed.length) {
  lines.push('');
  lines.push('Hints the lesson has already given (do not go further than these):');
  progress.hintsRevealed.forEach((hint, index) => lines.push('  ' + (index + 1) + '. ' + hint));
  lines.push('Hints left in the lesson: ' + (progress.hintsRemaining ?? 0));
}

lines.push('', '=== THIS STEP OF THE LESSON ===', lesson.chunkText || '(no lesson text)');

lines.push('', '=== REFERENCE WORKFLOW (hidden from the learner) ===');
if (d.canonical) {
  lines.push('Name: ' + d.canonical.name);
  lines.push('Node order: ' + (d.canonical.order || []).join(' > '));
  const withParams = (d.canonical.nodes || []).filter((n) => n.parameters);
  if (withParams.length) {
    lines.push('Node configuration:');
    lines.push(JSON.stringify(withParams).slice(0, 6000));
  } else {
    lines.push('Structure only at this help level - do not invent the configuration.');
  }
} else {
  lines.push('Not available at this help level. Do not guess what it contains.');
}

lines.push('', "=== THE LEARNER'S OWN WORKFLOW ===");
if (d.workflow) {
  lines.push('Name: ' + d.workflow.name + (d.workflow.active ? ' (published)' : ' (not published)'));
  lines.push(JSON.stringify(d.workflow.nodes).slice(0, 8000));
} else {
  lines.push(d.workflowNote || 'Not inspected for this question. Say so if it matters; do not invent it.');
}

lines.push('', '=== LATEST RUN ===');
if (d.execution) {
  lines.push(JSON.stringify(d.execution).slice(0, 8000));
} else {
  lines.push('Not inspected for this question. Do not invent a run, a node or an error.');
}

if (Array.isArray(d.history) && d.history.length) {
  lines.push('', '=== EARLIER IN THIS CONVERSATION ===');
  d.history.forEach((m) => lines.push((m.role === 'kaz' ? 'Kaz: ' : 'Learner: ') + m.content));
}

lines.push('', '=== THE LEARNER ASKS ===', d.question, '', 'Answer as Kaz.');

return { json: { prompt: lines.filter((line) => line !== undefined).join('\n'), looked: { workflow: !!d.workflow, execution: !!d.execution } } };

// One shape out, whatever the model did. AEP treats a 5xx as a model error and
// tells the learner honestly, so a failure here must not look like an answer.
const answer = String($json.text ?? $json.output ?? '').trim();
const looked = $('Build Kaz Prompt').item.json.looked || { workflow: false, execution: false };
return { json: { ok: answer.length > 0, answer: answer.slice(0, 4000), looked } };
